// O Error Trigger entrega um objeto com o que falhou.
// Reduzimos a um registro plano, pronto para gravar e para ler as 3 da manha.
const e = $json;
return [{
  json: {
    workflow_nome: e.workflow?.name ?? null,
    workflow_id:   e.workflow?.id ?? null,
    execucao_id:   e.execution?.id ?? null,
    execucao_url:  e.execution?.url ?? null,
    ultimo_no:     e.execution?.lastNodeExecuted ?? null,
    mensagem:      e.execution?.error?.message ?? 'sem mensagem',
    quando:        $now.toISO()
  }
}];
